function c(){return{code:"th-Th",currency:"TH"}}function s(t){const{code:n}=c();if(!t)return"";const o=Number(t);return new Intl.NumberFormat(n,{minimumFractionDigits:0,maximumFractionDigits:2}).format(o)}function i(t){const{code:n}=c();if(!t)return"";const o=Number(t);return new Intl.NumberFormat(n,{notation:"compact",maximumFractionDigits:2}).format(o).replace(/[A-Z]/g,e=>e.toLowerCase())}function b(t){if(!t)return"";if(t===0)return"0 Bytes";const n=["bytes","Kb","Mb","Gb","Tb","Pb","Eb","Zb","Yb"],o=2,r=1024,e=Number(t),m=Math.floor(Math.log(e)/Math.log(r));return`${parseFloat((e/r**m).toFixed(o))} ${n[m]}`}export{i as a,b,s as f};
